courte et exacte; sinon choisis le mode sans texte.\n\nPRÉSERVER\nConserve le produit, l’identité de marque fournie et tous les textes ou chiffres validés. Respecte les marges de sécurité du canal.\n\nÉVITER\nÉvite hiérarchie confuse, petit texte, faux avis, fausse réduction, CTA inventé, promesse invérifiable et surcharge. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Si la génération ou l’édition visuelle n’est pas disponible, livre un prompt final compatible avec un moteur d’image et précise le statut réel de la sortie.","sha256":"634c50a4ca3a3978c72b55cc713cafe4dcff50370443e13824418b272fdafc8f"}]$raccourcia$::jsonb) as x(
  ref text, moteur text, payload text, sha256 text
);

do $ctrl$
begin
  if (select count(*) from lot_v5_payloads) <> 30 then
    raise exception 'Lot 208 tronque : % lignes au lieu de 30.',
      (select count(*) from lot_v5_payloads);
  end if;
end $ctrl$;

-- 1. L'ancien courant sort du courant.
update public.prompt_versions pv
set is_current = false, status = 'retired'::public.version_status
from lot_v5_payloads l
join public.prompts p on p.external_ref = l.ref
join public.prompt_variants v on v.prompt_id = p.id
join public.ai_providers pr on pr.id = v.provider_id and pr.key = l.moteur
where pv.variant_id = v.id and pv.is_current and pv.payload is distinct from l.payload;

-- 2. Poser le nouveau texte la ou plus rien n'est courant.
insert into public.prompt_versions (variant_id, version_label, payload, status, is_current, published_at)
select v.id, 'v5-final', l.payload, 'published'::public.version_status, true, now()
from lot_v5_payloads l
join public.prompts p on p.external_ref = l.ref
join public.prompt_variants v on v.prompt_id = p.id
join public.ai_providers pr on pr.id = v.provider_id and pr.key = l.moteur
where not exists (
  select 1 from public.prompt_versions pv where pv.variant_id = v.id and pv.is_current
);

-- 3. Un texte identique deja archive redevient le courant : rejouer le lot ne
--    cree pas une version de plus.
update public.prompt_versions pv
set is_current = true, status = 'published'::public.version_status
from lot_v5_payloads l
join public.prompts p on p.external_ref = l.ref
join public.prompt_variants v on v.prompt_id = p.id
join public.ai_providers pr on pr.id = v.provider_id and pr.key = l.moteur
where pv.variant_id = v.id and pv.payload = l.payload and not pv.is_current
  and not exists (select 1 from public.prompt_versions a where a.variant_id = v.id and a.is_current);

do $ctrl$
declare
  v_pose integer;
begin
  select count(*) into v_pose
  from lot_v5_payloads l
  join public.prompts p on p.external_ref = l.ref
  join public.prompt_variants v on v.prompt_id = p.id
  join public.ai_providers pr on pr.id = v.provider_id and pr.key = l.moteur
  join public.prompt_versions pv on pv.variant_id = v.id and pv.is_current
  where pv.payload = l.payload;
  if v_pose <> 30 then
    raise exception 'Lot 208 : % payloads courants sur 30.', v_pose;
  end if;
end $ctrl$;

drop table lot_v5_payloads;
